/* =====================================================================
   M3M_1.O  —  Step 3: reference data (modules, chapter catalogue, benchmarks, key-ratio definitions, roles)
   Run in SSMS against M3M_One after 02_schema.sql.
   Runs only on an empty catalogue. Values are the app's starter catalogue - edit them in these tables to match your standards.
   ===================================================================== */
USE [M3M_One];
GO
SET NOCOUNT ON;
SET XACT_ABORT ON;
GO


IF EXISTS (SELECT 1 FROM dbo.modules)
BEGIN
    RAISERROR(N'Reference data already loaded - skipping 03_reference_data.sql', 10, 1) WITH NOWAIT;
    SET NOEXEC ON;
END
GO

BEGIN TRY
BEGIN TRANSACTION;

-- modules (36 rows)
SET IDENTITY_INSERT dbo.modules ON;
SET IDENTITY_INSERT dbo.modules OFF;

-- chapters (13 rows)
SET IDENTITY_INSERT dbo.chapters ON;
SET IDENTITY_INSERT dbo.chapters OFF;

-- chapterSections (105 rows)
SET IDENTITY_INSERT dbo.chapterSections ON;
SET IDENTITY_INSERT dbo.chapterSections OFF;

-- sectionFields (351 rows)
SET IDENTITY_INSERT dbo.sectionFields ON;
SET IDENTITY_INSERT dbo.sectionFields OFF;

-- benchmarks (49 rows)
SET IDENTITY_INSERT dbo.benchmarks ON;
SET IDENTITY_INSERT dbo.benchmarks OFF;

-- keyRatioCalFields (26 rows)
SET IDENTITY_INSERT dbo.keyRatioCalFields ON;
SET IDENTITY_INSERT dbo.keyRatioCalFields OFF;

-- comKeyRatioInputs (57 rows)
SET IDENTITY_INSERT dbo.comKeyRatioInputs ON;
SET IDENTITY_INSERT dbo.comKeyRatioInputs OFF;

-- comKeyRatioOutputs (24 rows)
SET IDENTITY_INSERT dbo.comKeyRatioOutputs ON;
SET IDENTITY_INSERT dbo.comKeyRatioOutputs OFF;

-- accessRoles (16 rows)
SET IDENTITY_INSERT dbo.accessRoles ON;
SET IDENTITY_INSERT dbo.accessRoles OFF;

COMMIT TRANSACTION;
PRINT 'Reference data loaded.';
END TRY
BEGIN CATCH
    IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
    PRINT 'Nothing was loaded - error: ' + ERROR_MESSAGE();
    THROW;
END CATCH
GO
SET NOEXEC OFF;
GO
